p=argparse.ArgumentParser(description=__doc__);p.add_argument('--step',type=Path,required=True);p.add_argument('--display-stl',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();a.output.mkdir(mode=0o700,exist_ok=False);sha=lambda x:hashlib.sha256(Path(x).read_bytes()).hexdigest();step_hash=sha(a.step);stl_hash=sha(a.display_stl);mesh=pv.read(str(a.display_stl));assert mesh.n_cells==384;points=mesh.points.copy();faces=mesh.faces.copy();c=np.array(mesh.center);section=mesh.slice(normal=(1,0,0),origin=(1000,0,0));assert section.n_cells>0;records={};started=time.monotonic()
